1	import { AgeBand, AgeBandDto, Country, CountryDto } from './country.model';
2	
3	const DEFAULT_LEGAL_AGE = 18;
4	
5	const isNum = (value: unknown): value is number =>
6	  typeof value === 'number' && Number.isFinite(value);
7	
8	/** Drops bands with from > to, factor <= 0 or non-finite values; missing list gives []. */
9	export function mapAgeBands(dtos: AgeBandDto[] | null | undefined): AgeBand[] {
10	  const bands: AgeBand[] = [];
11	  for (const dto of dtos ?? []) {
12	    const { fromAge, toAge, factor } = dto;
13	    if (isNum(fromAge) && isNum(toAge) && isNum(factor) && fromAge <= toAge && factor > 0) {
14	      bands.push({ fromAge, toAge, factor });
15	    }
16	  }
17	  return bands;
18	}
19	
20	export function mapCountry(dto: CountryDto): Country {
21	  return {
22	    code: dto.code.toLowerCase(),
23	    name: dto.name,
24	    legalAge:
25	      typeof dto.legalAge === 'number' && Number.isFinite(dto.legalAge) && dto.legalAge >= 0
26	        ? dto.legalAge
27	        : DEFAULT_LEGAL_AGE,
28	    currency: dto.currency ?? '',
29	    numberLocale: dto.numberLocale ?? '',
30	    driverAgeBands: mapAgeBands(dto.driverAgeBands),
31	    vehicleAgeBands: mapAgeBands(dto.vehicleAgeBands),
32	    iconUrl: dto.icon?.url ?? null,
33	    iconAlt: dto.icon?.alternativeText || dto.name,
34	  };
35	}
36	
37	export function mapCountries(dtos: CountryDto[]): Country[] {
38	  return dtos.map(mapCountry);
39	}
