1	import { HttpClient, HttpParams } from '@angular/common/http';
2	import { Injectable, inject } from '@angular/core';
3	import { Observable, map, shareReplay } from 'rxjs';
4	import { mapCountries } from './country.mapper';
5	import { CountriesResponseDto, Country } from './country.model';
6	
7	export function findCountryByCode(countries: Country[], code: string): Country | undefined {
8	  const wanted = code.toLowerCase();
9	  return countries.find((country) => country.code === wanted);
10	}
11	
12	@Injectable({ providedIn: 'root' })
13	export class CountryService {
14	  private readonly http = inject(HttpClient);
15	  private cached$: Observable<Country[]> | null = null;
16	
17	  /** Shared request: guard and page reuse the same result. Failures are not cached. */
18	  load(): Observable<Country[]> {
19	    if (!this.cached$) {
20	      const params = new HttpParams()
21	        .set('fields[0]', 'name')
22	        .set('fields[1]', 'code')
23	        .set('fields[2]', 'legalAge')
24	        .set('fields[3]', 'currency')
25	        .set('fields[4]', 'numberLocale')
26	        .set('populate[driverAgeBands]', 'true')
27	        .set('populate[vehicleAgeBands]', 'true')
28	        .set('populate[icon][fields][0]', 'url')
29	        .set('populate[icon][fields][1]', 'alternativeText')
30	        .set('sort', 'order:asc');
31	      const request$ = this.http.get<CountriesResponseDto>('/api/countries', { params }).pipe(
32	        map((response) => mapCountries(response.data)),
33	        shareReplay({ bufferSize: 1, refCount: false }),
34	      );
35	      this.cached$ = request$;
36	      // Drop the cache on failure so a retry issues a new request.
37	      request$.subscribe({
38	        error: () => {
39	          if (this.cached$ === request$) this.cached$ = null;
40	        },
41	      });
42	    }
43	    return this.cached$;
44	  }
45	
46	  /** Forces a fresh request (e.g. "Reintentar"). */
47	  reload(): Observable<Country[]> {
48	    this.cached$ = null;
49	    return this.load();
50	  }
51	
52	  findByCode(countries: Country[], code: string): Country | undefined {
53	    return findCountryByCode(countries, code);
54	  }
55	}
