1	import { isAllowedCharacters, type InputLimits } from '../validation/input-limits';
2	import type { FieldType } from '../validation/validation.model';
3	import type {
4	  FormFieldDescriptor,
5	  FormFieldDto,
6	  FormSection,
7	  FormSections,
8	} from './form-field.model';
9	
10	const FIELD_TYPES: readonly FieldType[] = ['text', 'number', 'select', 'date', 'checkbox'];
11	const SECTIONS: readonly FormSection[] = ['policyholder', 'vehicle'];
12	
13	function isFieldType(value: string): value is FieldType {
14	  return (FIELD_TYPES as readonly string[]).includes(value);
15	}
16	
17	function isSection(value: string): value is FormSection {
18	  return (SECTIONS as readonly string[]).includes(value);
19	}
20	
21	function mapInputLimits(dto: FormFieldDto): InputLimits {
22	  const chars = dto.validations?.allowedCharacters ?? null;
23	  if (chars !== null && !isAllowedCharacters(chars)) {
24	    console.warn(`Form field "${dto.key}": unknown allowedCharacters "${chars}" ignored.`);
25	  }
26	  const max = dto.validations?.maxLength ?? null;
27	  return {
28	    allowedCharacters: isAllowedCharacters(chars) ? chars : null,
29	    maxLength: max !== null && max > 0 ? max : null,
30	  };
31	}
32	
33	function mapField(dto: FormFieldDto, section: FormSection, type: FieldType): FormFieldDescriptor {
34	  return {
35	    key: dto.key,
36	    label: dto.label,
37	    type,
38	    required: dto.required,
39	    helpText: dto.helpText ?? null,
40	    placeholder: dto.placeholder ?? null,
41	    errorMessage: dto.errorMessage,
42	    order: dto.order,
43	    section,
44	    options: (dto.options ?? []).map((o) => ({ label: o.label, value: o.value })),
45	    rules: {
46	      type,
47	      required: dto.required,
48	      min: dto.validations?.min ?? null,
49	      max: dto.validations?.max ?? null,
50	      pattern: dto.validations?.pattern ?? null,
51	      validators: (dto.validations?.validators ?? []).map((v) => ({
52	        name: v.name,
53	        value: v.value ?? null,
54	      })),
55	    },
56	    inputLimits: mapInputLimits(dto),
57	  };
58	}
59	
60	/** Groups CMS fields by section, sorted by `order` (stable). Unknown types/sections are dropped. */
61	export function mapFormFields(dtos: FormFieldDto[]): FormSections {
62	  const result: FormSections = { policyholder: [], vehicle: [] };
63	  for (const dto of dtos) {
64	    if (!isSection(dto.section)) {
65	      console.warn(`Form field "${dto.key}" dropped: unknown section "${dto.section}".`);
66	      continue;
67	    }
68	    if (!isFieldType(dto.type)) {
69	      console.warn(`Form field "${dto.key}" dropped: unknown type "${dto.type}".`);
70	      continue;
71	    }
72	    result[dto.section].push(mapField(dto, dto.section, dto.type));
73	  }
74	  // Array.prototype.sort is stable: equal orders keep CMS order.
75	  result.policyholder.sort((a, b) => a.order - b.order);
76	  result.vehicle.sort((a, b) => a.order - b.order);
77	  return result;
78	}
