38	      (value) => value === true || (typeof value === 'string' && value.trim() !== ''),
39	    );
40	  }
41	
42	  readStep1(): Step1Values {
43	    const raw = this.read()?.data['step1'];
44	    if (typeof raw !== 'object' || raw === null || Array.isArray(raw)) return {};
45	    const values: Step1Values = {};
46	    for (const [key, value] of Object.entries(raw)) {
47	      if (typeof value === 'string' || typeof value === 'boolean') values[key] = value;
48	    }
49	    return values;
50	  }
51	
52	  /** Saves step 1 values; any earlier completion no longer applies. */
53	  saveStep1(values: Step1Values): void {
54	    const current = this.read();
55	    if (!current) return;
56	    const rest = { ...current.data };
57	    delete rest['step1Completed'];
58	    this.write({ countryCode: current.countryCode, data: { ...rest, step1: { ...values } } });
59	  }
60	
61	  markStep1Completed(): void {
62	    const current = this.read();
63	    if (!current) return;
64	    this.write({
65	      countryCode: current.countryCode,
66	      data: { ...current.data, step1Completed: true },
67	    });
68	  }
69	
70	  /** Step 1 no longer counts as complete (its saved values failed the re-check). */
71	  clearStep1Completed(): void {
72	    const current = this.read();
73	    if (!current) return;
74	    const rest = { ...current.data };
75	    delete rest['step1Completed'];
76	    this.write({ countryCode: current.countryCode, data: rest });
77	  }
78	
79	  /** R-02: the guard asks step 1 to show its errors once (consumed by `consumeStep1Review`). */
80	  flagStep1Review(): void {
81	    const current = this.read();
82	    if (!current) return;
83	    this.write({
84	      countryCode: current.countryCode,
85	      data: { ...current.data, step1Review: true },
86	    });
87	  }
88	
89	  /** Returns true once after `flagStep1Review`, then clears the flag. */
90	  consumeStep1Review(): boolean {
91	    const current = this.read();
92	    if (current?.data['step1Review'] !== true) return false;
93	    const rest = { ...current.data };
94	    delete rest['step1Review'];
95	    this.write({ countryCode: current.countryCode, data: rest });
96	    return true;
97	  }
98	
99	  isStep1Completed(): boolean {
100	    return this.read()?.data['step1Completed'] === true;
101	  }
102	
103	  /** Remembers the chosen plan (documentId) for this tab. */
104	  savePlan(planId: string): void {
105	    const current = this.read();
106	    if (!current) return;
107	    this.write({ countryCode: current.countryCode, data: { ...current.data, planId } });
108	  }
109	
110	  readPlanId(): string | null {
111	    const id = this.read()?.data['planId'];
112	    return typeof id === 'string' && id !== '' ? id : null;
113	  }
114	
115	  clearPlan(): void {
116	    const current = this.read();
117	    if (!current) return;
118	    const rest = { ...current.data };
119	    delete rest['planId'];
120	    this.write({ countryCode: current.countryCode, data: rest });
121	  }
122	
123	  /** Same country keeps data; a different country resets it. */
124	  start(countryCode: string): void {
125	    const current = this.read();
126	    const data = current?.countryCode === countryCode ? current.data : {};
127	    this.write({ countryCode, data });
128	  }
129	
130	  /** Keeps the country, empties the form data. */
131	  discardData(): void {
132	    const current = this.read();
133	    if (current) this.write({ countryCode: current.countryCode, data: {} });
134	  }
135	
136	  clear(): void {
137	    try {
138	      sessionStorage.removeItem(QUOTE_SESSION_KEY);
139	    } catch {
140	      /* storage unavailable */
141	    }
142	  }
143	
144	  private write(session: QuoteSession): void {
145	    try {
146	      sessionStorage.setItem(QUOTE_SESSION_KEY, JSON.stringify(session));
147	    } catch {
148	      /* storage unavailable: degrade to no persistence */
149	    }
150	  }
151	}
