3	/** Formats a whole-unit amount in the country's currency, no decimals, e.g. "$ 145.000 / mes". */
4	export function formatPrice(
5	  amount: number,
6	  country: Pick<Country, 'currency' | 'numberLocale'>,
7	): string {
8	  const locale = country.numberLocale || 'es';
9	  const digits = { minimumFractionDigits: 0, maximumFractionDigits: 0 };
10	  let formatted: string;
11	  try {
12	    formatted = new Intl.NumberFormat(locale, {
13	      ...digits,
14	      style: 'currency',
15	      currency: country.currency,
16	    }).format(amount);
17	  } catch {
18	    // R-12: a country with no (or an invalid) currency or locale must not break step 2.
19	    try {
20	      formatted = new Intl.NumberFormat(locale, digits).format(amount);
21	    } catch {
22	      formatted = new Intl.NumberFormat('es', digits).format(amount);
23	    }
24	  }
25	  return `${formatted} / mes`;
26	}
