import type { Step1Values } from '../../../core/session/quote-session.store';

const REJECTED_SUFFIX = '0000';

/**
 * Simulated payment outcome (rule in docs/adr/0006-simulated-payment-and-receipt.md).
 * Rejected when any field flagged `maskedInSummary` has a value whose letters and digits
 * (dots, hyphens and spaces removed) end in "0000", e.g. CO 1020300000 or CL 10.006.000-0.
 * Approved otherwise. Pure: no data leaves the browser.
 */
export function simulatePayment(
  values: Step1Values,
  maskedKeys: string[],
): 'approved' | 'rejected' {
  const rejected = maskedKeys.some((key) => {
    const value = values[key];
    if (typeof value !== 'string') return false;
    const normalised = value.replace(/[^\p{L}\p{N}]/gu, '');
    return normalised.endsWith(REJECTED_SUFFIX);
  });
  return rejected ? 'rejected' : 'approved';
}

import type { Step1Values } from '../../../core/session/quote-session.store';
import { simulatePayment } from './simulate-payment';

describe('US-03 · FR-007 simulated payment outcome (ADR 0006)', () => {
  const cases: [string, Step1Values, string[], 'approved' | 'rejected'][] = [
    ['CO document ending in 0000', { documentNumber: '1020300000' }, ['documentNumber'], 'rejected'],
    ['CL RUT 10.006.000-0 (separators ignored)', { rut: '10.006.000-0' }, ['rut'], 'rejected'],
    [
      'document not ending in 0000',
      { documentNumber: '1020304050' },
      ['documentNumber'],
      'approved',
    ],
    [
      '0000 only in an unmasked field',
      { plate: 'AB0000', documentNumber: '1020304050' },
      ['documentNumber'],
      'approved',
    ],
  ];

  it.each(cases)('%s', (_name, values, maskedKeys, expected) => {
    expect(simulatePayment(values, maskedKeys)).toBe(expected);
  });
});

/** 31 characters, without the look-alikes 0, O, 1, I, L (R3). */
export const QUOTE_ALPHABET = '23456789ABCDEFGHJKMNPQRSTUVWXYZ';
const SUFFIX_LENGTH = 6;

function cryptoRandom(max: number): number {
  const buffer = new Uint32Array(1);
  const limit = Math.floor(0x100000000 / max) * max;
  do {
    crypto.getRandomValues(buffer);
  } while (buffer[0] >= limit);
  return buffer[0] % max;
}

/** `CO-20261122-7KQ4MZ`. `random(max)` returns an integer in [0, max). */
export function createQuoteNumber(
  countryCode: string,
  now: Date,
  random: (max: number) => number = cryptoRandom,
): string {
  const pad = (n: number): string => String(n).padStart(2, '0');
  const date = `${now.getFullYear()}${pad(now.getMonth() + 1)}${pad(now.getDate())}`;
  let suffix = '';
  for (let i = 0; i < SUFFIX_LENGTH; i++) suffix += QUOTE_ALPHABET[random(QUOTE_ALPHABET.length)];
  return `${countryCode.toUpperCase()}-${date}-${suffix}`;
}

import { createQuoteNumber } from './quote-number';

describe('US-03 · FR-009 quote number', () => {
  const now = new Date(2026, 10, 22, 10, 0, 0);

  it('follows CC-YYYYMMDD-XXXXXX with no look-alike characters', () => {
    expect(createQuoteNumber('co', now)).toMatch(/^CO-20261122-[2-9A-HJKMNP-Z]{6}$/);
  });

  it('is built from the injected random source', () => {
    expect(createQuoteNumber('CL', now, () => 0)).toBe('CL-20261122-222222');
  });

  it('gives 1000 unique numbers', () => {
    const numbers = new Set(Array.from({ length: 1000 }, () => createQuoteNumber('CO', now)));
    expect(numbers.size).toBe(1000);
  });
});

import { Injectable } from '@angular/core';
import { Observable, map, timer } from 'rxjs';
import type { Step1Values } from '../../../core/session/quote-session.store';
import { simulatePayment } from './simulate-payment';

export const PAYMENT_DELAY_MS = 1500;

/** The single seam a real payment gateway would replace (ADR 0006). */
@Injectable({ providedIn: 'root' })
export class PaymentService {
  pay(values: Step1Values, maskedKeys: string[]): Observable<'approved' | 'rejected'> {
    return timer(PAYMENT_DELAY_MS).pipe(map(() => simulatePayment(values, maskedKeys)));
  }
}

